// Coral Vice - pack captured screenshots into screenshots-data.ts.
// Each image becomes ONE base64 string on ONE line: the make.fun
// transcript checks cannot cope with wrapped base64, and neither can
// we, so this file is generated, never hand-edited.
//
// Run:  node pack-screenshots.mjs     (reads screenshots-src/)
import { existsSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = dirname(fileURLToPath(import.meta.url));
const srcDir = join(root, 'screenshots-src');

if (!existsSync(srcDir)) {
  console.error('pack-screenshots: screenshots-src/ is missing - capture screenshots first');
  process.exit(1);
}

const files = readdirSync(srcDir)
  .filter((f) => /\.(png|jpe?g)$/i.test(f))
  .sort();

if (files.length < 3 || files.length > 4) {
  console.error(`pack-screenshots: need 3 or 4 images, found ${files.length}`);
  process.exit(1);
}

const lines = [];
lines.push('// GENERATED by pack-screenshots.mjs - do not edit by hand.');
lines.push('// Each payload is base64 on a single line, on purpose.');
lines.push('export const SCREENSHOTS: { name: string; base64: string }[] = [');

for (const file of files) {
  const bytes = readFileSync(join(srcDir, file));
  if (bytes.length > 262144) {
    console.error(`pack-screenshots: ${file} is ${bytes.length} bytes, over the 256 KiB cap`);
    process.exit(1);
  }
  lines.push(`  { name: ${JSON.stringify(file)}, base64: '${bytes.toString('base64')}' },`);
  console.log(`packed ${file} (${bytes.length} bytes)`);
}

lines.push('];');
lines.push('');
writeFileSync(join(root, 'screenshots-data.ts'), lines.join('\n'));
console.log(`wrote screenshots-data.ts with ${files.length} images`);
